select case when level in ('L1', 'L4') then 'group_a' else 'other' end as level_group, round((100 * sum(case when job_title = 'Intern' then 1 else 0 end)) / count(*), 1) as pct_intern, concat_ws(', ', sort_array(collect_set(job_title))) as job_title_values from employees where hire_date <= '2025-07-28' and job_title = 'Manager' group by case when level in ('L1', 'L4') then 'group_a' else 'other' end having round((100 * sum(case when job_title = 'Intern' then 1 else 0 end)) / count(*), 1) < 46 order by pct_intern desc, level_group
